function load$GridReport$(g) {
	g.add_onRender(on$GridReport$Render);
	g.add_commandEvent(on$GridReport$ExecuteCommand);
}
function dispose$GridReport$(g) {
	try {g.remove_commandEvent(on$GridReport$ExecuteCommand);} catch (ex) {}
	try {g.remove_onRender(on$GridReport$Render);} catch (ex) {}
}
function on$GridReport$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender;

	switch (action) {
		case 'View':
			e.type.cancelEvent = true;
			if ($func.trim(g._getItemValue(g._activeRow, g._getColumnOrder('&k;')))) g._navigate(g._activeCell, '&Url;');
			break;
		default:
			break;
	}
}

function passQueryParameters(g) {&Parameter;var a = [&Memvar;], c = $func.dataFieldName('&Fields;', g._language).split(','), seprate = &Seprate;;
	for (var i = 0; i < c.length; i++) {
		var name = $func.trim(c[i]).split(:), c1 = name[0], c2 = (name.length > 1 ? name[1] : c1);
		var value = (i < seprate ? $func.findMemvar(c1, g._memvars).NewValue : g._getItemValue(g._activeRow, g._getColumnOrder(c1)));
		var memvar = {Name: c2, Value: value};
		Array.add(a, memvar);
	}
	var session = {Memvar: a, Script: 'this._convection = true;'&Session;};
	g._passParameter(session);
}

function setGridHiddenFields(g, c, v) {
	var a = c.split(',');
	for (var i = 0; i < a.length; i++) {    
		g._setColumnVisible(g._getColumnOrder($func.trim(a[i])), !v);
	}
}

function formatDateView(c) {return String.format('{0}/{1}/{2}', c.substring(6, 8), c.substring(4, 6), c.substring(0, 4));}


function on$GridReport$Render(sender, eventArgs) {
	var g = eventArgs.grid;  
	if (g._hiddenFields) {
		var a = g._hiddenFields, h = '';
		for (var i = 0; i < a.length; i++) {
			setGridHiddenFields(g, a[i].Fields, a[i].Value);
			if (a[i].Value) h += (h == '' ? '' : ',') + a[i].Fields;
		}
		g._externalHiddenFields = h;
	}

	setColorWithCondition(g, 'systotal', '1', '', 'bold', '')
}
function beforeDrillDown(g) {
	var isCancel = !($func.trim(g._getItemValue(g._activeRow, g._activeColumn)));
	g._args_r = g._activeRow;

	if (!isCancel) {
		if (g._getItemValue(g._activeRow, g._getColumnOrder('xloai_tk')) == 1) {
			if ($func.trim(g._getItemValue(g._activeRow, g._getColumnOrder('&k;')))) g._navigate(g._activeCell, '&Url1;');
			g._args.cancelEvent = true;
			return;
		}
		if (g._getItemValue(g._activeRow, g._getColumnOrder('xloai_tk')) == 2) {
			if ($func.trim(g._getItemValue(g._activeRow, g._getColumnOrder('&k;')))) g._navigate(g._activeCell, '&Url2;');
			g._args.cancelEvent = true;
			return;
		}
		if (g._getItemValue(g._activeRow, g._getColumnOrder('xloai_tk')) == 3) {
			if ($func.trim(g._getItemValue(g._activeRow, g._getColumnOrder('&k;')))) g._navigate(g._activeCell, '&Url3;');
			g._args.cancelEvent = true;
			return;
		}
	}

	g._args.cancelEvent = isCancel;
}
function passQueryParameters$1(g) {
	var a = [];
	for (var i = 0; i < g._memvars.length; i++) {
		if (g._memvars[i].Name != 'xem_tk_nh' && g._memvars[i].Name != 'tk_1') 
